  42 const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
  43 const monitorPath = join(skillsDir, "pr-monitor/SKILL.md");
  44 const sweepPath = join(skillsDir, "pr-monitor/references/conflict-sweep.md");
  45 const backgroundPath = join(skillsDir, "pr-monitor/references/background-mode.md");
  46 const resolvePath = join(skillsDir, "pr-resolve/SKILL.md");
  47 const historyBlockPath = join(skillsDir, "shared-rules/references/git-history-policy.md");
  48 const docsPath = join(repoRoot, "docs/05-plan-run-skills.md");
  49 const readmePath = join(repoRoot, "claude-plugins/autopilot/README.md");
