  51 /** Shortest a real extraction can be; anything smaller means it went wrong. */
  52 const minExtractionLength = 40;
  53 
  54 /** The run-scoped sweep cap. Asserted as a literal — "a digit appears" would survive any edit. */
  55 const sweepCap = "capped at **2 per `pr-monitor` invocation**";
  56 
  57 const [monitor, resolve, historyBlock, sweepDoc, backgroundDoc] = await Promise.all([
  58   readFile(monitorPath, "utf8"),
  59   readFile(resolvePath, "utf8"),
  60   readFile(historyBlockPath, "utf8"),
  61   readFile(sweepPath, "utf8"),
  62   readFile(backgroundPath, "utf8"),
