  65 /** Extract a `### `/`## ` section by heading, up to the next heading of the same or higher level. */
  66 const section = (source: string, heading: string): string =>
  67   new RegExp(`^${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$[\\s\\S]*?(?=^#{1,3} )`, "m").exec(
  68     source,
  69   )?.[0] ?? "";
