  71 const sweep = sweepDoc;
  72 const earlyExit = section(monitor, "### 1.1 Early Exit Checks");
  73 const perCycle = section(monitor, "### 2.2 Check PR State");
  74 const backgroundMode = backgroundDoc;
  75 const detectPr = section(resolve, "### 1.1 Detect PR");
